function calculateOrderTotal(items: {price:number,quantity:number}[], discountRate:number) {
  const total = items.map(i => i.price * i.quantity).reduce((s, n) => s + n, 0);
  const discounted = total - total * discountRate;
  return discounted;
}

function canAccess(user: any) {
  return user.age >= 18 && user.subscription.active && (user.subscription.plan === 'pro' || user.isAdmin);
}

// Version A
function priceAfterTaxA(product: any) {
  const tax = product.taxRate;
  const base = product.basePrice;
  if (product.onSale) {
    return base * (1 + tax) * 0.9;
  }
  return base * (1 + tax);
}

// Version B
function priceAfterTaxB(product: any) {
  const base = product.basePrice;
  const taxed = base * (1 + product.taxRate);
  if (product.onSale) {
    return taxed * 0.9;
  }
  return taxed;
}
